package com.miniforce.dto;
import com.miniforce.model.*; import jakarta.validation.constraints.*; import java.time.*;
public final class SubmissionDtos { private SubmissionDtos(){} public record SubmissionRequest(@NotNull Long problemId,Long contestId,@NotBlank @Pattern(regexp="JAVA_17|PYTHON_3") String language,@NotBlank @Size(max=50000) String code) {} public record SubmissionResponse(Long id,Long problemId,String problemTitle,Long userId,String username,Long contestId,String language,SubmissionStatus status,Integer runtimeMs,Instant submittedAt,String compilerOutput,String runtimeErrorOutput,String systemErrorMessage) { public static SubmissionResponse from(Submission s){return new SubmissionResponse(s.getId(),s.getProblem().getId(),s.getProblem().getTitle(),s.getUser().getId(),s.getUser().getUsername(),s.getContest()==null?null:s.getContest().getId(),s.getLanguage(),s.getStatus(),s.getRuntimeMs(),s.getSubmittedAt(),s.getCompilerOutput(),s.getRuntimeErrorOutput(),s.getSystemErrorMessage());} } }
